// 자동 생성 — node scripts/seo-meta-voca.mjs (손으로 고치지 말 것 · 원천: apps/voca-tutorial/index.html DOC_TITLE·LANGS·T · i18n/<doc>.<lang>.html)
// functions/_middleware.js 가 ?lang=xx 응답의 title·description·OG·canonical 등을 이 값으로 바꾼다(packages/seo/README.md L3).
// TUT = 튜토리얼 본체(/) 13개 언어: t 제목 · d 설명 · l og:locale · a tutName · s 단계[제목, 설명] · sh/wh/w/fh/q 본문(소제목·이런 분께·FAQ) · f 푸터
export const TUT = {
  "en": {"t":"Learn the vocabulary memorizer in 10 steps | VOCA_TUTORIAL","d":"Learn the flashing vocabulary memorizer in 10 interactive steps: screen navigation, CSV decks, auto play, memorized marks, random order and TTS. Try each control yourself.","l":"en_US","a":"Flashing Vocabulary Memorizer tutorial","s":[["Welcome to the Flashing Memorizer","VOCA_DECK shows a word, then its meaning, in big letters over and over — so your brain links them by visual association. This 10-step tutorial teaches every control. Press Next to begin."],["Tap to advance","One tap shows the word, another reveals the meaning, and another moves to the next word. On a PC you can also press the spacebar. Try it on the screen above."],["Going back","Made a mistake? Press the ← key, scroll the wheel up, or swipe right on mobile to step backwards. Try it above."],["Open your own CSV deck","A deck is a plain CSV file: one line per entry, \"word,meaning\". Make it in Excel, Numbers or any text editor — no row limit. In the app, load it with the 📂 Open deck button."],["Manual / Auto mode","Auto mode advances by itself at the chosen delay (default 3 s) — perfect for hands-free repetition. Turn on Auto below and watch the screen."],["Order & start number","Study forward, backward, or in random order — random is great against memorizing the sequence instead of the words. The start number jumps to any position."],["Memorized marks & range","Mark a word as memorized and it drops out of the loop. The range setting lets you review only memorized words, or everything. Try marking the current word."],["A ↔ B direction","Flip the direction to be shown the meaning first and recall the word — the reverse test is where real memory is made. Try B → A below."],["Listen with TTS","The app can read entries aloud with your browser’s speech synthesis. Voice-only mode hides the text so you can train by ear. Turn it on and tap the screen."],["Make it yours & focus","Pick your font color and background (dark navy or black keeps the text crisp), then hide the control panel to study full-screen. That’s everything — you’re ready!"]],"sh":"The 10 steps","wh":"Who this tutorial is for","w":["First-time VOCA_DECK users who would rather learn by pressing the buttons than by reading instructions","Anyone who wants to check the \"word,meaning\" format before making their own CSV deck","Learners who want to try auto play, random order, A ↔ B direction and TTS before using them on a real deck","Anyone who wants to learn both the PC controls (spacebar, ← key) and the phone controls (tap, swipe) in one go"],"fh":"Frequently asked questions","q":[["Is the tutorial free? Do I need to install anything or sign up?","It is free. It opens right in your browser with no installation or sign-up. When you finish the last step, you can go straight to the VOCA_DECK app."],["Can I try the controls on the tutorial screen?","Yes. In each step you can use the mini screen and the buttons that step introduces. Tap the screen to advance, or turn on Auto mode, order, memorized marks, A ↔ B or TTS, and the result shows up on the mini screen right away."],["If I stop halfway, do I have to start over?","No. The step you were on is saved in this browser, so the tutorial resumes there when you come back. \"Skip tutorial\" takes you straight to the completion screen, and \"Restart tutorial\" there starts again from step 1 at any time."],["Are the settings I change in the tutorial saved in the app?","No. The tutorial is a practice screen that runs on three sample words, so it does not affect your decks or settings in the app. Real study starts when you open your own CSV deck in the app."],["How do I make a CSV deck?","All you need is a CSV file with one entry per line: the word and its meaning separated by a comma (\"word,meaning\"). You can make it in Excel, Numbers or any text editor, with no row limit. In the app, load it with the 📂 Open deck button."]],"f":["Site information","Home","VOCA_DECK app","Privacy Policy","Terms of Use","Contact & bug reports","made by {Y}","broodev is an app portfolio of free web apps that run right in your browser with no installation. Ads may be served through Google AdSense."]},
  "ja": {"t":"点滅式単語帳の使い方 · 10ステップチュートリアル | VOCA_TUTORIAL","d":"点滅式単語帳の使い方を10ステップの対話型デモで学べます。画面操作、CSV単語帳、自動再生、暗記マーク、ランダム順、TTSまで実際に触って確認。","l":"ja_JP","a":"点滅式単語帳チュートリアル","s":[["点滅式単語帳へようこそ","VOCA_DECKは単語と意味を大きな文字で交互に表示し、イメージ連想で記憶を結び付けるツールです。この10ステップですべての操作を学べます。「次へ」で始めましょう。"],["タップで進む","1回タップすると単語、もう1回で意味、さらにもう1回で次の単語に進みます。PCではスペースキーも使えます。上の画面で試してください。"],["戻る操作","間違えたら←キー、ホイール上、モバイルでは右スワイプで前に戻れます。上の画面で試してみましょう。"],["自分のCSV単語帳を開く","単語帳は1行に「単語,意味」と書くだけのCSVファイルです。Excelやメモ帳で作成でき、行数無制限。アプリでは📂「単語帳を開く」ボタンで読み込みます。"],["手動 / 自動モード","自動モードは設定した間隔（既定3秒）で勝手に進みます。ハンズフリー反復に最適。下の「自動」をオンにして画面を見てください。"],["順序と開始番号","順方向・逆方向・ランダムから選べます。ランダムは「並び順で覚えてしまう」のを防ぐのに効果的。開始番号で好きな位置から始められます。"],["暗記マークと表示範囲","覚えた単語にマークを付けると繰り返しから外れます。表示範囲で「暗記済のみ」の復習も可能。今の単語にマークを付けてみましょう。"],["A ↔ B 方向転換","意味を先に見て単語を思い出す逆方向出題もできます。逆テストこそ記憶が定着します。下でB → Aを試してください。"],["TTSで聞く","ブラウザの音声合成で読み上げできます。音声のみモードなら文字を隠して耳で訓練できます。オンにして画面をタップしてみてください。"],["画面を整えて集中","文字色と背景（濃紺か黒が見やすい）を選び、パネルを隠せば全画面で集中できます。これで全部です — 準備完了！"]],"sh":"10ステップの内容","wh":"こんな方におすすめ","w":["はじめてVOCA_DECKを使う方 — 説明を読むより、ボタンを実際に押しながら覚えたい方","自分のCSV単語帳を作る前に「単語,意味」の形式を確認しておきたい方","自動再生・ランダム順・A ↔ B 方向転換・TTS音声を、実際の単語帳で使う前に試しておきたい方","PC（スペースキー・←キー）とスマートフォン（タップ・スワイプ）の操作をまとめて知りたい方"],"fh":"よくある質問","q":[["チュートリアルは無料ですか？インストールや会員登録は必要ですか？","無料です。インストールも会員登録も不要で、ブラウザですぐに開けます。最後のステップまで終えると、そのままVOCA_DECK本体アプリへ移動できます。"],["チュートリアルの画面で実際に操作できますか？","はい。各ステップのミニ画面と、そのステップで紹介するボタンを実際に押せます。画面をタップして進めたり、自動モード・順序・暗記マーク・A ↔ B・TTSをオンにしたりすると、結果がすぐミニ画面に表示されます。"],["途中でやめたら最初からやり直しですか？","いいえ。表示中のステップはこのブラウザに保存され、次に開くとそのステップから再開します。「チュートリアルを飛ばす」を押すとすぐ完了画面に進み、完了画面の「最初からやり直す」でいつでもステップ1から見直せます。"],["チュートリアルで変えた設定は本体アプリに保存されますか？","いいえ。チュートリアルはサンプル単語3つで動く練習用の画面なので、本体アプリの単語帳や設定には影響しません。実際の暗記は、本体アプリで自分のCSV単語帳を開いて始めます。"],["CSV単語帳はどうやって作りますか？","1行に「単語,意味」のように単語と意味をカンマで区切って書いたCSVファイルがあれば大丈夫です。Excel・Numbers・メモ帳など何でも作れ、行数の制限はありません。本体アプリでは📂「単語帳を開く」ボタンで読み込みます。"]],"f":["サイト情報","ホーム","VOCA_DECK 本体アプリ","プライバシーポリシー","利用規約","お問い合わせ・不具合報告","制作: {Y}","broodevは、インストール不要でブラウザからすぐ使える無料Webアプリを作るアプリポートフォリオです。広告はGoogle AdSenseを通じて掲載される場合があります。"]},
  "ko": {"t":"깜빡이 단어암기장 사용법 · 10단계 튜토리얼 | VOCA_TUTORIAL","d":"깜빡이 단어암기장 사용법을 10단계 인터랙티브 데모로 배웁니다. 화면 진행, CSV 암기장, 자동 재생, 암기 표시, 무작위 순서, TTS까지 직접 눌러보며 익히세요.","l":"ko_KR","a":"깜빡이 단어암기장 튜토리얼","s":[["깜빡이 단어암기장에 오신 것을 환영합니다","VOCA_DECK은 단어와 뜻을 큰 글자로 번갈아 보여주며 이미지 연상으로 기억을 연결하는 도구입니다. 이 튜토리얼 10단계로 모든 조작을 익힐 수 있습니다. \"다음\"을 눌러 시작하세요."],["눌러서 진행하기","한 번 누르면 단어, 또 누르면 뜻, 또 누르면 다음 단어로 넘어갑니다. PC에서는 스페이스바도 됩니다. 위 화면에서 직접 해보세요."],["뒤로 가기","실수했다면 ← 키, 휠 위로, 모바일에서는 오른쪽 스와이프로 이전 단계로 돌아갑니다. 위에서 시험해 보세요."],["내 CSV 암기장 열기","암기장은 한 줄에 \"단어,뜻\"만 적으면 되는 CSV 파일입니다. 엑셀·메모장 어디서든 만들 수 있고 행 수 제한이 없습니다. 앱에서는 📂 암기장 열기 버튼으로 불러옵니다."],["수동 / 자동 모드","자동 모드는 설정한 지연시간(기본 3초) 간격으로 저절로 진행됩니다. 손을 떼고 반복하기에 최적. 아래에서 자동을 켜고 화면을 지켜보세요."],["출제 순서와 시작번호","순방향·역방향·무작위 중 고를 수 있습니다. 무작위는 \"순서로 외워버리는\" 것을 막는 데 효과적입니다. 시작번호로 원하는 위치부터 시작하세요."],["암기 표시와 표시 범위","외운 단어에 암기 표시를 하면 반복에서 빠집니다. 표시 범위로 외운 항목만 복습할 수도 있습니다. 지금 단어에 표시를 해보세요."],["A ↔ B 방향 전환","뜻을 먼저 보고 단어를 떠올리는 역방향 출제도 가능합니다. 역방향 테스트에서 진짜 기억이 만들어집니다. 아래에서 B → A를 켜보세요."],["TTS로 듣기","브라우저 음성 합성으로 단어를 읽어줍니다. 음성만 모드는 글자를 숨기고 귀로 훈련할 수 있게 해줍니다. 켜고 화면을 눌러보세요."],["화면 꾸미기와 집중 모드","글자색과 배경(짙은 남색·검정 권장)을 고르고, 제어판을 숨기면 전체 화면으로 집중할 수 있습니다. 이게 전부입니다 — 준비 완료!"]],"sh":"10단계 구성","wh":"이런 분께 좋습니다","w":["VOCA_DECK을 처음 쓰는 분 — 설명을 읽기보다 버튼을 직접 눌러 보며 익히고 싶은 분","나만의 CSV 암기장을 만들기 전에 \"단어,뜻\" 형식을 먼저 확인하고 싶은 분","자동 재생·무작위 순서·A ↔ B 방향 전환·TTS 음성을 실제 암기장에 쓰기 전에 미리 시험해 보고 싶은 분","PC(스페이스바·← 키)와 스마트폰(탭·스와이프) 조작을 한 번에 알고 싶은 분"],"fh":"자주 묻는 질문","q":[["튜토리얼은 무료인가요? 설치나 회원가입이 필요한가요?","무료입니다. 설치와 회원가입 없이 브라우저에서 바로 열립니다. 마지막 단계를 마치면 바로 VOCA_DECK 본 앱으로 이동할 수 있습니다."],["튜토리얼 화면에서 직접 조작해 볼 수 있나요?","네. 각 단계의 미니 화면과 그 단계에서 소개하는 버튼을 직접 눌러 볼 수 있습니다. 화면을 눌러 넘기거나 자동 모드·출제 순서·암기 표시·A ↔ B·TTS를 켜면 결과가 미니 화면에 바로 나타납니다."],["중간에 그만두면 처음부터 다시 해야 하나요?","아니요. 보고 있던 단계는 이 브라우저에 저장되어 다시 열면 그 단계부터 이어집니다. \"튜토리얼 건너뛰기\"를 누르면 바로 완료 화면으로 가고, 완료 화면의 \"처음부터 다시\"로 언제든 1단계부터 다시 볼 수 있습니다."],["튜토리얼에서 바꾼 설정이 본 앱에 저장되나요?","아니요. 튜토리얼은 예시 단어 3개로 동작하는 연습 화면이라 본 앱의 암기장과 설정에는 영향을 주지 않습니다. 실제 암기는 본 앱에서 나만의 CSV 암기장을 열어 시작합니다."],["CSV 암기장은 어떻게 만드나요?","한 줄에 \"단어,뜻\"처럼 단어와 뜻을 쉼표로 구분해 적은 CSV 파일이면 됩니다. 엑셀·Numbers·메모장 등 어디서든 만들 수 있고 행 수 제한은 없습니다. 본 앱에서 📂 암기장 열기 버튼으로 불러옵니다."]],"f":["사이트 정보","홈","VOCA_DECK 본 앱","개인정보처리방침","이용약관","문의 & 버그 신고","{Y} 제작","broodev는 설치 없이 브라우저에서 바로 쓰는 무료 웹앱을 만드는 앱 포트폴리오입니다. 광고는 Google AdSense를 통해 게재될 수 있습니다."]},
  "zh": {"t":"闪示单词记忆使用教程 · 10步 | VOCA_TUTORIAL","d":"通过10步交互式演示学习闪示单词记忆工具的用法：画面操作、CSV单词本、自动播放、已记标记、随机顺序与TTS，边点边学。","l":"zh_CN","a":"闪示单词记忆教程","s":[["欢迎使用闪示单词记忆","VOCA_DECK以大字交替显示单词和释义，通过图像联想连接记忆。本教程共10步，覆盖全部操作。点击\"下一步\"开始。"],["点按前进","点一下显示单词，再点一下显示释义，再点一下进入下一个单词。PC上也可以按空格键。在上方屏幕试试吧。"],["后退操作","按错了？按←键、滚轮向上，或在手机上向右滑动即可后退。在上方试试。"],["打开自己的CSV单词本","单词本就是每行\"单词,释义\"的CSV文件。用Excel或记事本都能做，行数不限。在应用中用📂\"打开单词本\"按钮载入。"],["手动 / 自动模式","自动模式按设定间隔（默认3秒）自动前进，适合解放双手反复记忆。在下方打开\"自动\"并观察屏幕。"],["顺序与起始编号","可选正向、反向或随机。随机能防止\"按顺序背下来\"的假记忆。起始编号可以跳到任意位置。"],["已记标记与显示范围","给记住的单词打上标记，它就会退出循环。显示范围还能只复习已记单词。给当前单词打个标记试试。"],["A ↔ B 方向切换","也可以先看释义再回想单词——反向测试才能形成真正的记忆。在下方试试B → A。"],["用TTS听","应用可用浏览器语音合成朗读条目。仅语音模式隐藏文字，用耳朵训练。打开后点一下屏幕试试。"],["个性化与专注模式","选择文字颜色和背景（深蓝或黑色最清晰），再隐藏控制面板即可全屏专注学习。就是这些——你准备好了！"]],"sh":"10个步骤","wh":"适合这些人","w":["第一次使用VOCA_DECK、比起阅读说明更想亲手点按学习的人","在制作自己的CSV单词本之前，想先确认\"单词,释义\"格式的人","想在真正的单词本上使用之前，先试试自动播放、随机顺序、A ↔ B 方向切换和TTS语音的人","想一次了解电脑（空格键、←键）和手机（点按、滑动）两种操作方式的人"],"fh":"常见问题","q":[["教程是免费的吗？需要安装或注册吗？","免费。无需安装或注册，直接在浏览器中打开。完成最后一步后，可以直接进入VOCA_DECK正式应用。"],["可以在教程画面上亲手操作吗？","可以。每一步都能亲手点按迷你画面和该步骤介绍的按钮。点按画面前进，或打开自动模式、顺序、已记标记、A ↔ B、TTS，结果会立即显示在迷你画面上。"],["中途退出的话需要从头开始吗？","不需要。正在看的步骤会保存在此浏览器中，再次打开时从该步骤继续。点击\"跳过教程\"会直接进入完成画面，在完成画面点击\"重新开始\"可随时从第1步重新学习。"],["在教程中更改的设置会保存到正式应用吗？","不会。教程是用3个示例单词运行的练习画面，不会影响正式应用中的单词本和设置。真正的记忆从在正式应用中打开你自己的CSV单词本开始。"],["怎样制作CSV单词本？","只需一个CSV文件，每行像\"单词,释义\"这样用逗号分隔单词和释义。用Excel、Numbers或记事本等都能制作，行数不限。在正式应用中用📂\"打开单词本\"按钮载入。"]],"f":["网站信息","首页","VOCA_DECK 正式应用","隐私政策","使用条款","联系与错误反馈","由 {Y} 制作","broodev 是一个应用作品集，制作无需安装、在浏览器中即可直接使用的免费网页应用。广告可能通过 Google AdSense 投放。"]},
  "zh-Hant": {"t":"閃示單字記憶使用教學 · 10步 | VOCA_TUTORIAL","d":"透過10步互動式示範學習閃示單字記憶工具的用法：畫面操作、CSV單字本、自動播放、已記標記、隨機順序與TTS，邊點邊學。","l":"zh_TW","a":"閃示單字記憶教學","s":[["歡迎使用閃示單字記憶","VOCA_DECK以大字交替顯示單字與釋義，透過圖像聯想連結記憶。本教學共10步，涵蓋全部操作。點「下一步」開始。"],["點按前進","點一下顯示單字，再點一下顯示釋義，再點一下進入下一個單字。PC上也可以按空白鍵。在上方螢幕試試吧。"],["後退操作","按錯了？按←鍵、滾輪向上，或在手機上向右滑動即可後退。在上方試試。"],["開啟自己的CSV單字本","單字本就是每行「單字,釋義」的CSV檔案。用Excel或記事本都能做，行數不限。在應用中用📂「開啟單字本」按鈕載入。"],["手動 / 自動模式","自動模式依設定間隔（預設3秒）自動前進，適合解放雙手反覆記憶。在下方開啟「自動」並觀察螢幕。"],["順序與起始編號","可選正向、反向或隨機。隨機能防止「按順序背下來」的假記憶。起始編號可以跳到任意位置。"],["已記標記與顯示範圍","給記住的單字打上標記，它就會退出循環。顯示範圍還能只複習已記單字。給目前單字打個標記試試。"],["A ↔ B 方向切換","也可以先看釋義再回想單字——反向測試才能形成真正的記憶。在下方試試B → A。"],["用TTS聽","應用可用瀏覽器語音合成朗讀條目。僅語音模式隱藏文字，用耳朵訓練。開啟後點一下螢幕試試。"],["個人化與專注模式","選擇文字顏色和背景（深藍或黑色最清晰），再隱藏控制面板即可全螢幕專注學習。就是這些——你準備好了！"]],"sh":"10個步驟","wh":"適合這些人","w":["第一次使用VOCA_DECK、比起閱讀說明更想親手點按學習的人","在製作自己的CSV單字本之前，想先確認「單字,釋義」格式的人","想在真正的單字本上使用之前，先試試自動播放、隨機順序、A ↔ B 方向切換和TTS語音的人","想一次了解電腦（空白鍵、←鍵）和手機（點按、滑動）兩種操作方式的人"],"fh":"常見問題","q":[["教學是免費的嗎？需要安裝或註冊嗎？","免費。無需安裝或註冊，直接在瀏覽器中開啟。完成最後一步後，可以直接進入VOCA_DECK正式應用。"],["可以在教學畫面上親手操作嗎？","可以。每一步都能親手點按迷你畫面和該步驟介紹的按鈕。點按畫面前進，或開啟自動模式、順序、已記標記、A ↔ B、TTS，結果會立即顯示在迷你畫面上。"],["中途離開的話需要從頭開始嗎？","不需要。正在看的步驟會儲存在此瀏覽器中，再次開啟時從該步驟繼續。點選「跳過教學」會直接進入完成畫面，在完成畫面點選「重新開始」可隨時從第1步重新學習。"],["在教學中變更的設定會儲存到正式應用嗎？","不會。教學是用3個範例單字運作的練習畫面，不會影響正式應用中的單字本和設定。真正的記憶從在正式應用中開啟你自己的CSV單字本開始。"],["怎麼製作CSV單字本？","只需一個CSV檔案，每行像「單字,釋義」這樣用逗號分隔單字和釋義。用Excel、Numbers或記事本等都能製作，行數不限。在正式應用中用📂「開啟單字本」按鈕載入。"]],"f":["網站資訊","首頁","VOCA_DECK 正式應用","隱私權政策","使用條款","聯絡與錯誤回報","由 {Y} 製作","broodev 是一個應用作品集，製作免安裝、在瀏覽器中即可直接使用的免費網頁應用。廣告可能透過 Google AdSense 刊登。"]},
  "th": {"t":"วิธีใช้แอปท่องศัพท์แบบแฟลชใน 10 ขั้น | VOCA_TUTORIAL","d":"เรียนรู้วิธีใช้แอปท่องศัพท์แบบแฟลชผ่านการสาธิตแบบโต้ตอบ 10 ขั้นตอน: การควบคุมหน้าจอ, ชุดคำศัพท์ CSV, เล่นอัตโนมัติ, เครื่องหมายจำ, สุ่มลำดับ และ TTS","l":"th_TH","a":"บทช่วยสอนแอปท่องศัพท์แบบแฟลช","s":[["ยินดีต้อนรับสู่แอปท่องศัพท์แบบแฟลช","VOCA_DECK แสดงคำและความหมายสลับกันด้วยตัวอักษรขนาดใหญ่ ให้สมองเชื่อมโยงผ่านภาพ บทช่วยสอน 10 ขั้นนี้ครอบคลุมทุกการควบคุม กด \"ถัดไป\" เพื่อเริ่ม"],["แตะเพื่อไปต่อ","แตะครั้งแรกแสดงคำ แตะอีกครั้งแสดงความหมาย แตะอีกครั้งไปคำถัดไป บน PC ใช้สเปซบาร์ได้ ลองที่หน้าจอด้านบน"],["การย้อนกลับ","พลาดไป? กดปุ่ม ← เลื่อนล้อขึ้น หรือปัดขวาบนมือถือเพื่อถอยหลัง ลองดูด้านบน"],["เปิดชุดคำศัพท์ CSV ของคุณ","ชุดคำศัพท์คือไฟล์ CSV ธรรมดา บรรทัดละ \"คำ,ความหมาย\" สร้างได้ใน Excel หรือโปรแกรมแก้ไขข้อความใดๆ ไม่จำกัดแถว ในแอปให้โหลดด้วยปุ่ม 📂 เปิดชุดคำศัพท์"],["โหมดมือ / อัตโนมัติ","โหมดอัตโนมัติเลื่อนเองตามหน่วงเวลา (ค่าเริ่มต้น 3 วิ) เหมาะกับการทวนแบบไม่ต้องใช้มือ เปิด \"อัตโนมัติ\" ด้านล่างแล้วดูหน้าจอ"],["ลำดับและหมายเลขเริ่มต้น","เลือกไปข้างหน้า ย้อนกลับ หรือสุ่มได้ การสุ่มช่วยกันการจำ \"ตามลำดับ\" แทนที่จะจำคำ หมายเลขเริ่มต้นใช้กระโดดไปตำแหน่งใดก็ได้"],["เครื่องหมายจำและขอบเขต","ทำเครื่องหมายคำที่จำได้แล้ว มันจะออกจากรอบวน ขอบเขตยังให้ทวนเฉพาะคำที่จำได้ ลองทำเครื่องหมายคำปัจจุบันดู"],["สลับทิศ A ↔ B","สลับให้เห็นความหมายก่อนแล้วนึกคำ — การทดสอบย้อนกลับคือจุดที่ความจำจริงเกิดขึ้น ลอง B → A ด้านล่าง"],["ฟังด้วย TTS","แอปอ่านออกเสียงด้วยเสียงสังเคราะห์ของเบราว์เซอร์ได้ โหมดเสียงเท่านั้นซ่อนตัวอักษรให้ฝึกด้วยหู เปิดแล้วแตะหน้าจอดู"],["ปรับแต่งและโฟกัส","เลือกสีตัวอักษรและพื้นหลัง (น้ำเงินเข้มหรือดำคมชัดสุด) แล้วซ่อนแผงควบคุมเพื่อเรียนแบบเต็มจอ ครบแล้ว — พร้อมลุย!"]],"sh":"10 ขั้นตอน","wh":"เหมาะสำหรับใคร","w":["ผู้ที่เพิ่งเริ่มใช้ VOCA_DECK และอยากเรียนรู้ด้วยการกดปุ่มจริงมากกว่าการอ่านคำอธิบาย","ผู้ที่อยากดูรูปแบบ \"คำศัพท์,ความหมาย\" ก่อนสร้างชุดคำศัพท์ CSV ของตัวเอง","ผู้ที่อยากลองเล่นอัตโนมัติ ลำดับสุ่ม การสลับทิศ A ↔ B และเสียง TTS ก่อนใช้กับชุดคำศัพท์จริง","ผู้ที่อยากรู้วิธีควบคุมทั้งบนคอมพิวเตอร์ (สเปซบาร์ ปุ่ม ←) และบนสมาร์ตโฟน (แตะ ปัด) ในคราวเดียว"],"fh":"คำถามที่พบบ่อย","q":[["บทช่วยสอนนี้ฟรีไหม ต้องติดตั้งหรือสมัครสมาชิกหรือเปล่า","ฟรี ไม่ต้องติดตั้งหรือสมัครสมาชิก เปิดในเบราว์เซอร์ได้ทันที เมื่อจบขั้นตอนสุดท้ายแล้วไปที่แอป VOCA_DECK ได้เลย"],["ลองกดใช้งานบนหน้าบทช่วยสอนได้จริงไหม","ได้ ในแต่ละขั้นตอนคุณกดหน้าจอย่อและปุ่มที่ขั้นตอนนั้นแนะนำได้จริง แตะหน้าจอเพื่อไปต่อ หรือเปิดโหมดอัตโนมัติ ลำดับ เครื่องหมายจำ A ↔ B หรือ TTS แล้วผลลัพธ์จะแสดงบนหน้าจอย่อทันที"],["ถ้าหยุดกลางคัน ต้องเริ่มใหม่ตั้งแต่ต้องไหม","ไม่ต้อง ขั้นตอนที่ดูค้างไว้จะถูกบันทึกในเบราว์เซอร์นี้ เมื่อเปิดอีกครั้งจะเริ่มต่อจากขั้นตอนนั้น กด \"ข้ามบทช่วยสอน\" เพื่อไปหน้าจบทันที และกด \"เริ่มใหม่\" ในหน้าจบเพื่อดูตั้งแต่ขั้นตอนที่ 1 ได้ทุกเมื่อ"],["การตั้งค่าที่เปลี่ยนในบทช่วยสอนจะถูกบันทึกในแอปหลักไหม","ไม่ บทช่วยสอนเป็นหน้าจอฝึกที่ทำงานด้วยคำตัวอย่าง 3 คำ จึงไม่มีผลกับชุดคำศัพท์และการตั้งค่าในแอปหลัก การท่องจริงเริ่มเมื่อคุณเปิดชุดคำศัพท์ CSV ของตัวเองในแอปหลัก"],["สร้างชุดคำศัพท์ CSV อย่างไร","ใช้ไฟล์ CSV ที่เขียนบรรทัดละหนึ่งรายการ โดยคั่นคำศัพท์กับความหมายด้วยจุลภาค เช่น \"คำศัพท์,ความหมาย\" สร้างได้ใน Excel, Numbers หรือโปรแกรมแก้ไขข้อความใดก็ได้ ไม่จำกัดจำนวนบรรทัด ในแอปให้โหลดด้วยปุ่ม 📂 เปิดชุดคำศัพท์"]],"f":["ข้อมูลเว็บไซต์","หน้าแรก","แอป VOCA_DECK","นโยบายความเป็นส่วนตัว","ข้อกำหนดการใช้งาน","ติดต่อและแจ้งข้อผิดพลาด","สร้างโดย {Y}","broodev คือพอร์ตโฟลิโอของเว็บแอปฟรีที่ใช้งานได้ทันทีในเบราว์เซอร์โดยไม่ต้องติดตั้ง โฆษณาอาจแสดงผ่าน Google AdSense"]},
  "es": {"t":"Cómo usar el memorizador en 10 pasos | VOCA_TUTORIAL","d":"Aprende el memorizador de vocabulario en 10 pasos interactivos: navegación, mazos CSV, reproducción automática, marcas, orden aleatorio y TTS. Pruébalo tú mismo.","l":"es_ES","a":"Tutorial del memorizador de vocabulario","s":[["Bienvenido al memorizador flash","VOCA_DECK muestra una palabra y luego su significado en letras grandes, una y otra vez, para que tu cerebro los asocie visualmente. Este tutorial de 10 pasos cubre todos los controles. Pulsa Siguiente."],["Toca para avanzar","Un toque muestra la palabra, otro revela el significado y otro pasa a la siguiente. En PC también sirve la barra espaciadora. Pruébalo en la pantalla de arriba."],["Retroceder","¿Te pasaste? Pulsa la tecla ←, rueda del ratón hacia arriba, o desliza a la derecha en el móvil. Pruébalo arriba."],["Abre tu propio mazo CSV","Un mazo es un simple archivo CSV: una línea por entrada, \"palabra,significado\". Créalo en Excel o cualquier editor, sin límite de filas. En la app se carga con el botón 📂 Abrir mazo."],["Modo manual / automático","El modo auto avanza solo según el intervalo (3 s por defecto), ideal para repetir sin manos. Activa Auto abajo y observa la pantalla."],["Orden y número inicial","Estudia hacia delante, hacia atrás o en orden aleatorio: lo aleatorio evita memorizar la secuencia en vez de las palabras. El número inicial salta a cualquier posición."],["Marcas y rango","Marca una palabra como memorizada y saldrá del ciclo. El rango permite repasar solo las memorizadas, o todas. Prueba a marcar la palabra actual."],["Dirección A ↔ B","Invierte la dirección para ver primero el significado y recordar la palabra: la prueba inversa es donde se fija la memoria. Prueba B → A abajo."],["Escucha con TTS","La app puede leer en voz alta con la síntesis de voz del navegador. El modo solo voz oculta el texto para entrenar de oído. Actívalo y toca la pantalla."],["Personaliza y concéntrate","Elige color de letra y fondo (azul marino oscuro o negro se ve más nítido) y oculta el panel para estudiar a pantalla completa. Eso es todo: ¡listo!"]],"sh":"Los 10 pasos","wh":"¿Para quién es este tutorial?","w":["Quienes usan VOCA_DECK por primera vez y prefieren aprender pulsando los botones en lugar de leer instrucciones","Quienes quieren ver el formato \"palabra,significado\" antes de crear su propio mazo CSV","Quienes quieren probar la reproducción automática, el orden aleatorio, la dirección A ↔ B y el TTS antes de usarlos con un mazo real","Quienes quieren conocer de una vez los controles en PC (barra espaciadora, tecla ←) y en el móvil (tocar, deslizar)"],"fh":"Preguntas frecuentes","q":[["¿El tutorial es gratuito? ¿Hay que instalar algo o registrarse?","Es gratuito. Se abre directamente en el navegador, sin instalación ni registro. Al terminar el último paso puedes ir directamente a la app VOCA_DECK."],["¿Puedo probar los controles en la pantalla del tutorial?","Sí. En cada paso puedes usar la minipantalla y los botones que presenta ese paso. Toca la pantalla para avanzar o activa el modo automático, el orden, las marcas, A ↔ B o el TTS, y verás el resultado al instante en la minipantalla."],["Si lo dejo a medias, ¿tengo que empezar de nuevo?","No. El paso en el que estabas se guarda en este navegador, así que al volver continúas desde ahí. «Saltar tutorial» te lleva directamente a la pantalla final, y allí «Reiniciar tutorial» vuelve al paso 1 cuando quieras."],["¿Los ajustes que cambio en el tutorial se guardan en la app?","No. El tutorial es una pantalla de práctica que funciona con tres palabras de ejemplo, así que no afecta a tus mazos ni a tus ajustes de la app. El estudio real empieza cuando abres tu propio mazo CSV en la app."],["¿Cómo creo un mazo CSV?","Basta con un archivo CSV con una entrada por línea: la palabra y su significado separados por una coma (\"palabra,significado\"). Puedes crearlo en Excel, Numbers o cualquier editor de texto, sin límite de filas. En la app, cárgalo con el botón 📂 Abrir mazo."]],"f":["Información del sitio","Inicio","App VOCA_DECK","Política de privacidad","Términos de uso","Contacto e informes de errores","creado por {Y}","broodev es un portafolio de aplicaciones web gratuitas que funcionan directamente en el navegador, sin instalación. Es posible que se muestren anuncios a través de Google AdSense."]},
  "fr": {"t":"Tutoriel de mémorisation en 10 étapes | VOCA_TUTORIAL","d":"Apprenez la mémorisation de vocabulaire en 10 étapes interactives : navigation, paquets CSV, lecture auto, marques, ordre aléatoire et TTS. Essayez chaque commande.","l":"fr_FR","a":"Tutoriel de mémorisation de vocabulaire","s":[["Bienvenue dans la mémorisation flash","VOCA_DECK affiche un mot puis son sens en grands caractères, encore et encore, pour que votre cerveau les associe visuellement. Ce tutoriel en 10 étapes couvre toutes les commandes. Appuyez sur Suivant."],["Touchez pour avancer","Un appui montre le mot, un autre révèle le sens, un autre passe au mot suivant. Sur PC, la barre d’espace fonctionne aussi. Essayez sur l’écran ci-dessus."],["Revenir en arrière","Une erreur ? Touche ←, molette vers le haut, ou glissement à droite sur mobile pour reculer. Essayez ci-dessus."],["Ouvrez votre paquet CSV","Un paquet est un simple fichier CSV : une ligne par entrée, « mot,sens ». Créez-le dans Excel ou tout éditeur, sans limite de lignes. Dans l’app, chargez-le avec le bouton 📂 Ouvrir un paquet."],["Mode manuel / auto","Le mode auto avance seul selon l’intervalle (3 s par défaut), parfait pour répéter mains libres. Activez Auto ci-dessous et regardez l’écran."],["Ordre et numéro de départ","Étudiez en avant, en arrière ou au hasard — l’aléatoire évite de mémoriser la séquence au lieu des mots. Le numéro de départ saute à n’importe quelle position."],["Marques et plage","Marquez un mot comme mémorisé et il sort de la boucle. La plage permet de revoir uniquement les mémorisés, ou tout. Essayez de marquer le mot actuel."],["Direction A ↔ B","Inversez pour voir d’abord le sens et retrouver le mot : le test inverse est là où la mémoire se fixe. Essayez B → A ci-dessous."],["Écoutez avec TTS","L’app peut lire à voix haute grâce à la synthèse vocale du navigateur. Le mode voix seule masque le texte pour entraîner l’oreille. Activez-le et touchez l’écran."],["Personnalisez et concentrez-vous","Choisissez couleur et fond (bleu marine foncé ou noir pour un texte net), puis masquez le panneau pour étudier en plein écran. C’est tout — vous êtes prêt !"]],"sh":"Les 10 étapes","wh":"À qui s’adresse ce tutoriel ?","w":["Aux nouveaux utilisateurs de VOCA_DECK qui préfèrent apprendre en appuyant sur les boutons plutôt qu’en lisant des explications","À ceux qui veulent voir le format « mot,sens » avant de créer leur propre paquet CSV","À ceux qui veulent essayer la lecture auto, l’ordre aléatoire, la direction A ↔ B et la synthèse vocale (TTS) avant de les utiliser sur un vrai paquet","À ceux qui veulent découvrir d’un coup les commandes sur PC (barre d’espace, touche ←) et sur téléphone (toucher, balayer)"],"fh":"Questions fréquentes","q":[["Le tutoriel est-il gratuit ? Faut-il installer quelque chose ou créer un compte ?","Il est gratuit. Il s’ouvre directement dans le navigateur, sans installation ni inscription. Une fois la dernière étape terminée, vous pouvez passer directement à l’application VOCA_DECK."],["Peut-on essayer les commandes sur l’écran du tutoriel ?","Oui. À chaque étape, vous pouvez utiliser le mini-écran et les boutons présentés à cette étape. Touchez l’écran pour avancer ou activez le mode auto, l’ordre, les marques, A ↔ B ou le TTS : le résultat s’affiche aussitôt sur le mini-écran."],["Si j’arrête en cours de route, faut-il tout recommencer ?","Non. L’étape en cours est enregistrée dans ce navigateur : le tutoriel reprend là où vous vous étiez arrêté. « Passer le tutoriel » mène directement à l’écran de fin, où « Recommencer » vous ramène à l’étape 1 à tout moment."],["Les réglages modifiés dans le tutoriel sont-ils enregistrés dans l’application ?","Non. Le tutoriel est un écran d’entraînement qui fonctionne avec trois mots d’exemple ; il n’a aucun effet sur vos paquets ni sur vos réglages dans l’application. La vraie mémorisation commence quand vous ouvrez votre propre paquet CSV dans l’application."],["Comment créer un paquet CSV ?","Il suffit d’un fichier CSV avec une entrée par ligne : le mot et son sens séparés par une virgule (« mot,sens »). Vous pouvez le créer dans Excel, Numbers ou n’importe quel éditeur de texte, sans limite de lignes. Dans l’application, chargez-le avec le bouton 📂 Ouvrir un paquet."]],"f":["Informations sur le site","Accueil","Application VOCA_DECK","Politique de confidentialité","Conditions d’utilisation","Contact et signalement de bugs","créé par {Y}","broodev est un portfolio d’applications web gratuites qui fonctionnent directement dans le navigateur, sans installation. Des publicités peuvent être diffusées via Google AdSense."]},
  "de": {"t":"Vokabeltrainer-Anleitung in 10 Schritten | VOCA_TUTORIAL","d":"Lerne den Vokabeltrainer in 10 interaktiven Schritten: Bedienung, CSV-Decks, Autoplay, Markierungen, Zufallsreihenfolge und TTS. Probiere jede Funktion selbst aus.","l":"de_DE","a":"Vokabeltrainer-Tutorial","s":[["Willkommen beim Blitz-Vokabeltrainer","VOCA_DECK zeigt Wort und Bedeutung abwechselnd in großer Schrift — dein Gehirn verknüpft sie über visuelle Assoziation. Dieses 10-Schritte-Tutorial erklärt alle Funktionen. Drücke Weiter."],["Tippen zum Fortfahren","Ein Tipp zeigt das Wort, ein weiterer die Bedeutung, der nächste springt zum nächsten Wort. Am PC geht auch die Leertaste. Probier es oben aus."],["Zurückgehen","Verklickt? Drücke ←, scrolle nach oben oder wische auf dem Handy nach rechts, um zurückzugehen. Probier es oben."],["Eigenes CSV-Deck öffnen","Ein Deck ist eine einfache CSV-Datei: eine Zeile pro Eintrag, \"Wort,Bedeutung\". Erstellbar in Excel oder jedem Editor, ohne Zeilenlimit. In der App lädst du es mit 📂 Deck öffnen."],["Manuell / Auto-Modus","Der Auto-Modus läuft von selbst im gewählten Intervall (Standard 3 s) — ideal fürs freihändige Wiederholen. Schalte unten Auto ein und beobachte den Bildschirm."],["Reihenfolge & Startnummer","Lerne vorwärts, rückwärts oder zufällig — Zufall verhindert, dass du die Reihenfolge statt der Wörter lernst. Die Startnummer springt an jede Position."],["Markierungen & Bereich","Markiere ein Wort als gemerkt und es fällt aus der Schleife. Über den Bereich kannst du auch nur Gemerktes wiederholen. Markiere das aktuelle Wort."],["Richtung A ↔ B","Dreh die Richtung um: erst die Bedeutung sehen, das Wort erinnern — im Rückwärtstest entsteht echtes Gedächtnis. Probiere unten B → A."],["Mit TTS hören","Die App liest Einträge per Browser-Sprachsynthese vor. Der Nur-Ton-Modus versteckt den Text zum Hörtraining. Einschalten und auf den Bildschirm tippen."],["Anpassen & fokussieren","Wähle Schriftfarbe und Hintergrund (dunkles Marineblau oder Schwarz ist am schärfsten) und blende das Panel aus, um im Vollbild zu lernen. Das war’s — du bist bereit!"]],"sh":"Die 10 Schritte","wh":"Für wen ist dieses Tutorial?","w":["Für alle, die VOCA_DECK zum ersten Mal nutzen und die Knöpfe lieber selbst ausprobieren, als Anleitungen zu lesen","Für alle, die sich das Format „Wort,Bedeutung“ ansehen möchten, bevor sie ihr eigenes CSV-Deck anlegen","Für alle, die Autoplay, Zufallsreihenfolge, die Richtung A ↔ B und die Sprachausgabe (TTS) ausprobieren möchten, bevor sie sie mit einem echten Deck nutzen","Für alle, die die Bedienung am PC (Leertaste, ←-Taste) und am Smartphone (Tippen, Wischen) auf einmal kennenlernen möchten"],"fh":"Häufige Fragen","q":[["Ist das Tutorial kostenlos? Muss ich etwas installieren oder mich registrieren?","Es ist kostenlos. Es öffnet sich direkt im Browser, ohne Installation und ohne Registrierung. Nach dem letzten Schritt kannst du direkt zur VOCA_DECK-App wechseln."],["Kann ich die Bedienung im Tutorial selbst ausprobieren?","Ja. In jedem Schritt kannst du den Mini-Bildschirm und die Knöpfe benutzen, die der Schritt vorstellt. Tippe auf den Bildschirm, um weiterzugehen, oder schalte Auto-Modus, Reihenfolge, Markierungen, A ↔ B oder TTS ein – das Ergebnis erscheint sofort auf dem Mini-Bildschirm."],["Muss ich von vorn anfangen, wenn ich mittendrin aufhöre?","Nein. Der Schritt, bei dem du warst, wird in diesem Browser gespeichert, und beim nächsten Öffnen geht es dort weiter. „Tutorial überspringen“ führt direkt zum Abschlussbildschirm, und dort startet „Von vorn beginnen“ jederzeit wieder bei Schritt 1."],["Werden Einstellungen aus dem Tutorial in der App gespeichert?","Nein. Das Tutorial ist ein Übungsbildschirm mit drei Beispielwörtern und hat keinen Einfluss auf deine Decks oder Einstellungen in der App. Richtig gelernt wird, sobald du in der App dein eigenes CSV-Deck öffnest."],["Wie erstelle ich ein CSV-Deck?","Du brauchst nur eine CSV-Datei mit einem Eintrag pro Zeile: Wort und Bedeutung, durch ein Komma getrennt („Wort,Bedeutung“). Du kannst sie in Excel, Numbers oder jedem Texteditor anlegen, ohne Zeilenlimit. In der App lädst du sie mit dem Knopf 📂 Deck öffnen."]],"f":["Website-Informationen","Startseite","VOCA_DECK-App","Datenschutzerklärung","Nutzungsbedingungen","Kontakt & Fehlermeldungen","erstellt von {Y}","broodev ist ein Portfolio kostenloser Web-Apps, die ohne Installation direkt im Browser laufen. Werbung kann über Google AdSense ausgeliefert werden."]},
  "it": {"t":"Come usare il memorizzatore in 10 passi | VOCA_TUTORIAL","d":"Impara il memorizzatore di vocaboli in 10 passi interattivi: navigazione, mazzi CSV, riproduzione automatica, contrassegni, ordine casuale e TTS. Prova ogni comando.","l":"it_IT","a":"Tutorial del memorizzatore di vocaboli","s":[["Benvenuto nel memorizzatore flash","VOCA_DECK mostra una parola e poi il suo significato a caratteri grandi, più volte, così il cervello li collega per associazione visiva. Questo tutorial in 10 passi copre tutti i comandi. Premi Avanti."],["Tocca per avanzare","Un tocco mostra la parola, un altro rivela il significato, un altro passa alla successiva. Su PC funziona anche la barra spaziatrice. Provalo sullo schermo qui sopra."],["Tornare indietro","Sbagliato? Premi ←, rotella verso l’alto, o scorri a destra su mobile per tornare indietro. Prova qui sopra."],["Apri il tuo mazzo CSV","Un mazzo è un semplice file CSV: una riga per voce, \"parola,significato\". Crealo con Excel o qualsiasi editor, senza limiti di righe. Nell’app si carica con 📂 Apri mazzo."],["Modalità manuale / auto","La modalità auto avanza da sola secondo l’intervallo (3 s di default), perfetta per ripetere a mani libere. Attiva Auto qui sotto e osserva lo schermo."],["Ordine e numero iniziale","Studia in avanti, all’indietro o a caso — il casuale evita di memorizzare la sequenza invece delle parole. Il numero iniziale salta a qualsiasi posizione."],["Contrassegni e ambito","Contrassegna una parola come memorizzata e uscirà dal ciclo. L’ambito permette di ripassare solo le memorizzate, o tutte. Prova a contrassegnare la parola attuale."],["Direzione A ↔ B","Inverti la direzione: prima il significato, poi ricordi la parola — il test inverso è dove la memoria si fissa davvero. Prova B → A qui sotto."],["Ascolta con TTS","L’app può leggere ad alta voce con la sintesi vocale del browser. La modalità solo voce nasconde il testo per allenare l’orecchio. Attivala e tocca lo schermo."],["Personalizza e concentrati","Scegli colore del testo e sfondo (blu scuro o nero è più nitido), poi nascondi il pannello per studiare a schermo intero. È tutto: sei pronto!"]],"sh":"I 10 passi","wh":"A chi è rivolto questo tutorial","w":["A chi usa VOCA_DECK per la prima volta e preferisce imparare premendo i pulsanti anziché leggere le istruzioni","A chi vuole vedere il formato \"parola,significato\" prima di creare il proprio mazzo CSV","A chi vuole provare la riproduzione automatica, l’ordine casuale, la direzione A ↔ B e la sintesi vocale (TTS) prima di usarle con un mazzo vero","A chi vuole conoscere in un colpo solo i comandi su PC (barra spaziatrice, tasto ←) e su smartphone (tocco, scorrimento)"],"fh":"Domande frequenti","q":[["Il tutorial è gratuito? Serve installare qualcosa o registrarsi?","È gratuito. Si apre direttamente nel browser, senza installazione né registrazione. Finito l’ultimo passo, puoi passare subito all’app VOCA_DECK."],["Posso provare i comandi nella schermata del tutorial?","Sì. In ogni passo puoi usare il mini schermo e i pulsanti presentati in quel passo. Tocca lo schermo per avanzare oppure attiva la modalità automatica, l’ordine, i contrassegni, A ↔ B o il TTS: il risultato compare subito sul mini schermo."],["Se mi fermo a metà, devo ricominciare da capo?","No. Il passo a cui eri arrivato viene salvato in questo browser e, quando torni, il tutorial riprende da lì. «Salta il tutorial» porta subito alla schermata finale, dove «Ricomincia» riparte dal passo 1 in qualsiasi momento."],["Le impostazioni cambiate nel tutorial vengono salvate nell’app?","No. Il tutorial è una schermata di prova che funziona con tre parole di esempio, quindi non influisce sui tuoi mazzi né sulle impostazioni dell’app. Lo studio vero comincia quando apri il tuo mazzo CSV nell’app."],["Come si crea un mazzo CSV?","Basta un file CSV con una voce per riga: la parola e il suo significato separati da una virgola (\"parola,significato\"). Puoi crearlo con Excel, Numbers o qualsiasi editor di testo, senza limiti di righe. Nell’app caricalo con il pulsante 📂 Apri mazzo."]],"f":["Informazioni sul sito","Inizio","App VOCA_DECK","Informativa sulla privacy","Termini di utilizzo","Contatti e segnalazione bug","creato da {Y}","broodev è un portfolio di app web gratuite che funzionano direttamente nel browser, senza installazione. Gli annunci possono essere pubblicati tramite Google AdSense."]},
  "pt": {"t":"Como usar o memorizador em 10 passos | VOCA_TUTORIAL","d":"Aprende o memorizador de vocabulário em 10 passos interativos: navegação, baralhos CSV, reprodução automática, marcas, ordem aleatória e TTS. Experimenta cada comando.","l":"pt_PT","a":"Tutorial do memorizador de vocabulário","s":[["Bem-vindo ao memorizador flash","O VOCA_DECK mostra uma palavra e depois o significado em letras grandes, repetidamente, para o cérebro os ligar por associação visual. Este tutorial de 10 passos cobre todos os comandos. Carrega em Seguinte."],["Toca para avançar","Um toque mostra a palavra, outro revela o significado e outro passa à seguinte. No PC também funciona a barra de espaço. Experimenta no ecrã acima."],["Recuar","Enganaste-te? Prime ←, roda a roda para cima, ou desliza para a direita no telemóvel. Experimenta acima."],["Abre o teu baralho CSV","Um baralho é um simples ficheiro CSV: uma linha por entrada, \"palavra,significado\". Cria-o no Excel ou em qualquer editor, sem limite de linhas. Na app carrega-se com 📂 Abrir baralho."],["Modo manual / auto","O modo auto avança sozinho no intervalo escolhido (3 s por defeito) — perfeito para repetir sem mãos. Ativa Auto em baixo e observa o ecrã."],["Ordem e número inicial","Estuda para a frente, para trás ou aleatoriamente — o aleatório evita memorizar a sequência em vez das palavras. O número inicial salta para qualquer posição."],["Marcas e âmbito","Marca uma palavra como memorizada e ela sai do ciclo. O âmbito permite rever só as memorizadas, ou todas. Experimenta marcar a palavra atual."],["Direção A ↔ B","Inverte a direção: vê primeiro o significado e recorda a palavra — o teste inverso é onde a memória se fixa. Experimenta B → A em baixo."],["Ouvir com TTS","A app pode ler em voz alta com a síntese de voz do navegador. O modo só voz esconde o texto para treinar de ouvido. Ativa-o e toca no ecrã."],["Personaliza e concentra-te","Escolhe a cor do texto e o fundo (azul-escuro ou preto fica mais nítido) e oculta o painel para estudar em ecrã inteiro. É tudo — estás pronto!"]],"sh":"Os 10 passos","wh":"Para quem é este tutorial","w":["Para quem usa o VOCA_DECK pela primeira vez e prefere aprender a carregar nos botões em vez de ler instruções","Para quem quer ver o formato \"palavra,significado\" antes de criar o próprio baralho CSV","Para quem quer experimentar a reprodução automática, a ordem aleatória, a direção A ↔ B e a voz TTS antes de as usar num baralho a sério","Para quem quer conhecer de uma só vez os controlos no computador (barra de espaço, tecla ←) e no telemóvel (tocar, deslizar)"],"fh":"Perguntas frequentes","q":[["O tutorial é gratuito? É preciso instalar alguma coisa ou criar conta?","É gratuito. Abre diretamente no navegador, sem instalação nem registo. Ao terminar o último passo, podes ir logo para a app VOCA_DECK."],["Posso experimentar os controlos no ecrã do tutorial?","Sim. Em cada passo podes usar o mini-ecrã e os botões apresentados nesse passo. Toca no ecrã para avançar ou liga o modo automático, a ordem, as marcas, A ↔ B ou o TTS, e o resultado aparece logo no mini-ecrã."],["Se parares a meio, tens de começar do início?","Não. O passo em que estavas fica guardado neste navegador e, quando voltares, o tutorial continua a partir daí. «Saltar tutorial» leva-te diretamente ao ecrã final, onde «Recomeçar» volta ao passo 1 sempre que quiseres."],["As definições que mudas no tutorial ficam guardadas na app?","Não. O tutorial é um ecrã de treino que funciona com três palavras de exemplo, por isso não afeta os teus baralhos nem as definições da app. O estudo a sério começa quando abres o teu próprio baralho CSV na app."],["Como crio um baralho CSV?","Basta um ficheiro CSV com uma entrada por linha: a palavra e o significado separados por uma vírgula (\"palavra,significado\"). Podes criá-lo no Excel, no Numbers ou em qualquer editor de texto, sem limite de linhas. Na app, carrega-o com o botão 📂 Abrir baralho."]],"f":["Informações do site","Início","App VOCA_DECK","Política de privacidade","Termos de utilização","Contacto e relatórios de erros","criado por {Y}","O broodev é um portefólio de aplicações web gratuitas que funcionam diretamente no navegador, sem instalação. Podem ser apresentados anúncios através do Google AdSense."]},
  "ru": {"t":"Как пользоваться тренажёром слов: 10 шагов | VOCA_TUTORIAL","d":"Освойте тренажёр слов за 10 интерактивных шагов: управление, CSV-наборы, автоповтор, отметки, случайный порядок и озвучка. Попробуйте каждую функцию сами.","l":"ru_RU","a":"Обучение работе с тренажёром слов","s":[["Добро пожаловать в флеш-тренажёр","VOCA_DECK показывает слово, затем его значение крупным шрифтом, снова и снова — мозг связывает их через зрительную ассоциацию. Эти 10 шагов охватывают всё управление. Нажмите «Далее»."],["Касание — вперёд","Одно касание показывает слово, второе — значение, третье — следующее слово. На ПК работает и пробел. Попробуйте на экране выше."],["Назад","Промахнулись? Клавиша ←, колесо вверх или свайп вправо на телефоне вернут назад. Попробуйте выше."],["Откройте свой CSV-набор","Набор — это простой CSV-файл: одна строка на запись, «слово,значение». Создаётся в Excel или любом редакторе, без лимита строк. В приложении загружается кнопкой 📂 «Открыть набор»."],["Ручной / автоматический режим","Авторежим листает сам с заданным интервалом (по умолчанию 3 с) — идеально для повторения без рук. Включите «Авто» ниже и смотрите на экран."],["Порядок и стартовый номер","Учите вперёд, назад или вразброс — случайный порядок не даёт запомнить последовательность вместо слов. Стартовый номер переносит в любую позицию."],["Отметки и диапазон","Отметьте слово как выученное — и оно выпадет из цикла. Диапазон позволяет повторять только выученное или всё. Отметьте текущее слово."],["Направление A ↔ B","Переверните направление: сначала значение, потом вспоминаете слово — обратный тест и создаёт настоящую память. Попробуйте B → A ниже."],["Слушайте с TTS","Приложение озвучивает записи синтезом речи браузера. Режим «только звук» скрывает текст для тренировки на слух. Включите и коснитесь экрана."],["Настройте под себя и фокус","Выберите цвет текста и фон (тёмно-синий или чёрный — самые чёткие), затем скройте панель и занимайтесь на весь экран. Это всё — вы готовы!"]],"sh":"10 шагов","wh":"Кому подойдёт это обучение","w":["Тем, кто впервые открывает VOCA_DECK и предпочитает осваивать кнопки на практике, а не читать инструкции","Тем, кто хочет увидеть формат «слово,значение» перед тем, как составить свой CSV-набор","Тем, кто хочет попробовать автоповтор, случайный порядок, направление A ↔ B и озвучку TTS до того, как использовать их с настоящим набором","Тем, кто хочет сразу узнать управление на компьютере (пробел, клавиша ←) и на телефоне (касание, свайп)"],"fh":"Частые вопросы","q":[["Обучение бесплатное? Нужно что-то устанавливать или регистрироваться?","Да, бесплатное. Оно открывается прямо в браузере, без установки и регистрации. Пройдя последний шаг, можно сразу перейти в приложение VOCA_DECK."],["Можно ли попробовать управление прямо на экране обучения?","Да. На каждом шаге можно нажимать на мини-экран и кнопки, о которых рассказывает этот шаг. Коснитесь экрана, чтобы идти дальше, или включите автоматический режим, порядок, отметки, A ↔ B или TTS — результат сразу появится на мини-экране."],["Если остановиться на середине, придётся начинать заново?","Нет. Шаг, на котором вы остановились, сохраняется в этом браузере, и при следующем открытии обучение продолжится с него. «Пропустить обучение» сразу ведёт на финальный экран, а кнопка «Начать заново» на нём в любой момент возвращает к шагу 1."],["Сохраняются ли настройки из обучения в приложении?","Нет. Обучение — это тренировочный экран с тремя примерами слов, поэтому оно не влияет на ваши наборы и настройки в приложении. Настоящее заучивание начинается, когда вы открываете свой CSV-набор в приложении."],["Как составить CSV-набор?","Нужен только CSV-файл, где в каждой строке записаны слово и его значение через запятую («слово,значение»). Его можно создать в Excel, Numbers или любом текстовом редакторе, без ограничения по числу строк. В приложении загрузите его кнопкой 📂 Открыть набор."]],"f":["Информация о сайте","Главная","Приложение VOCA_DECK","Политика конфиденциальности","Условия использования","Связь и сообщения об ошибках","разработано {Y}","broodev — портфолио бесплатных веб-приложений, которые работают прямо в браузере без установки. Реклама может показываться через Google AdSense."]},
  "nl": {"t":"Woordjestrainer-tutorial in 10 stappen | VOCA_TUTORIAL","d":"Leer de woordjestrainer in 10 interactieve stappen: bediening, CSV-decks, autoplay, markeringen, willekeurige volgorde en TTS. Probeer elke functie zelf.","l":"nl_NL","a":"Tutorial woordjestrainer","s":[["Welkom bij de flits-woordjestrainer","VOCA_DECK toont een woord en daarna de betekenis in grote letters, telkens opnieuw — je brein koppelt ze via visuele associatie. Deze tutorial van 10 stappen behandelt alle functies. Druk op Volgende."],["Tik om verder te gaan","Eén tik toont het woord, nog één onthult de betekenis en nog één gaat naar het volgende woord. Op de pc werkt ook de spatiebalk. Probeer het op het scherm hierboven."],["Teruggaan","Misgetikt? Druk op ←, scrol omhoog of veeg op mobiel naar rechts om terug te gaan. Probeer het hierboven."],["Open je eigen CSV-deck","Een deck is een simpel CSV-bestand: één regel per item, \"woord,betekenis\". Te maken in Excel of elke editor, zonder regellimiet. In de app laad je het met 📂 Deck openen."],["Handmatig / automatisch","De automodus gaat vanzelf verder volgens het interval (standaard 3 s) — ideaal voor handsfree herhalen. Zet Auto hieronder aan en kijk naar het scherm."],["Volgorde en startnummer","Leer vooruit, achteruit of willekeurig — willekeurig voorkomt dat je de volgorde onthoudt in plaats van de woorden. Met het startnummer spring je naar elke positie."],["Markeringen en bereik","Markeer een woord als geleerd en het valt uit de lus. Met het bereik herhaal je alleen geleerde woorden, of alles. Markeer het huidige woord eens."],["Richting A ↔ B","Draai de richting om: eerst de betekenis zien en het woord herinneren — de omgekeerde test is waar echt geheugen ontstaat. Probeer B → A hieronder."],["Luisteren met TTS","De app kan items voorlezen met de spraaksynthese van de browser. De alleen-geluid-modus verbergt de tekst om op het gehoor te trainen. Zet aan en tik op het scherm."],["Maak het eigen & focus","Kies tekstkleur en achtergrond (donker marineblauw of zwart is het scherpst) en verberg het paneel om schermvullend te studeren. Dat is alles — je bent klaar!"]],"sh":"De 10 stappen","wh":"Voor wie is deze tutorial?","w":["Als je VOCA_DECK voor het eerst gebruikt en liever zelf op de knoppen drukt dan uitleg leest","Als je het formaat \"woord,betekenis\" wilt zien voordat je je eigen CSV-deck maakt","Als je autoplay, willekeurige volgorde, de richting A ↔ B en TTS wilt uitproberen voordat je ze met een echt deck gebruikt","Als je in één keer de bediening op de pc (spatiebalk, ←-toets) en op je telefoon (tikken, vegen) wilt leren"],"fh":"Veelgestelde vragen","q":[["Is de tutorial gratis? Moet ik iets installeren of een account aanmaken?","Hij is gratis. Hij opent direct in je browser, zonder installatie of account. Na de laatste stap kun je meteen naar de VOCA_DECK-app."],["Kan ik de bediening zelf uitproberen in de tutorial?","Ja. In elke stap kun je het minischerm en de knoppen gebruiken die die stap uitlegt. Tik op het scherm om verder te gaan of zet de automatische modus, volgorde, markeringen, A ↔ B of TTS aan, en je ziet het resultaat meteen op het minischerm."],["Moet ik opnieuw beginnen als ik halverwege stop?","Nee. De stap waar je was, wordt in deze browser bewaard, dus de volgende keer ga je daar verder. Met \"Tutorial overslaan\" ga je direct naar het eindscherm, en daar begin je met \"Opnieuw beginnen\" altijd weer bij stap 1."],["Worden instellingen uit de tutorial in de app bewaard?","Nee. De tutorial is een oefenscherm met drie voorbeeldwoorden en heeft dus geen invloed op je decks of instellingen in de app. Echt leren begint zodra je je eigen CSV-deck in de app opent."],["Hoe maak ik een CSV-deck?","Je hebt alleen een CSV-bestand nodig met één item per regel: woord en betekenis, gescheiden door een komma (\"woord,betekenis\"). Je kunt het maken in Excel, Numbers of elke teksteditor, zonder limiet op het aantal regels. Laad het in de app met de knop 📂 Deck openen."]],"f":["Website-informatie","Startpagina","VOCA_DECK-app","Privacybeleid","Gebruiksvoorwaarden","Contact & foutmeldingen","gemaakt door {Y}","broodev is een portfolio van gratis webapps die zonder installatie direct in je browser werken. Advertenties kunnen via Google AdSense worden weergegeven."]},
};

